import{_ as a,c as r,o as d,j as n,Y as s,t as o}from"./chunks/framework.BNTND4LZ.js";const f=JSON.parse('{"title":"tr | x-cmd man (man1) | translate or delete characters","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | tr - translate or delete characters","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"tr | x-cmd man (man1) | translate or delete characters"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | tr - translate or delete characters"}]]},"headers":[],"params":{"isMan":true,"man":"tr","category":"man1","desc":"translate or delete characters"},"relativePath":"man1/tr.md","filePath":"man1/[man].md"}'),l={name:"man1/tr.md"},i={class:"visually-hidden"};function c(e,t,h,p,g,u){return d(),r("div",null,[n("h1",i,o(e.$params.man),1),t[0]||(t[0]=s('<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>tr - translate or delete characters</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>tr</strong> [<em>OPTION</em>]... *STRING1 *[<em>STRING2</em>]</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>Translate, squeeze, and/or delete characters from standard input, writing to standard output. STRING1 and STRING2 specify arrays of characters ARRAY1 and ARRAY2 that control the action.</p><dl><dt><strong>-c</strong>, <strong>-C</strong>, <strong>--complement</strong></dt><dd>use the complement of ARRAY1</dd><dt><strong>-d</strong>, <strong>--delete</strong></dt><dd>delete characters in ARRAY1, do not translate</dd><dt><strong>-s</strong>, <strong>--squeeze-repeats</strong></dt><dd>replace each sequence of a repeated character that is listed in the last specified ARRAY, with a single occurrence of that character</dd><dt><strong>-t</strong>, <strong>--truncate-set1</strong></dt><dd>first truncate ARRAY1 to length of ARRAY2</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>ARRAYs are specified as strings of characters. Most represent themselves. Interpreted sequences are:</p><dl><dt>\\NNN</dt><dd>character with octal value NNN (1 to 3 octal digits)</dd><dt>\\\\ <br></dt><dd>backslash</dd><dt>\\a</dt><dd>audible BEL</dd><dt>\\b</dt><dd>backspace</dd><dt>\\f</dt><dd>form feed</dd><dt>\\n</dt><dd>new line</dd><dt>\\r</dt><dd>return</dd><dt>\\t</dt><dd>horizontal tab</dd><dt>\\v</dt><dd>vertical tab</dd><dt>CHAR1-CHAR2</dt><dd>all characters from CHAR1 to CHAR2 in ascending order</dd><dt>[CHAR*]</dt><dd>in ARRAY2, copies of CHAR until length of ARRAY1</dd><dt>[CHAR*REPEAT]</dt><dd>REPEAT copies of CHAR, REPEAT octal if starting with 0</dd><dt>[:alnum:]</dt><dd>all letters and digits</dd><dt>[:alpha:]</dt><dd>all letters</dd><dt>[:blank:]</dt><dd>all horizontal whitespace</dd><dt>[:cntrl:]</dt><dd>all control characters</dd><dt>[:digit:]</dt><dd>all digits</dd><dt>[:graph:]</dt><dd>all printable characters, not including space</dd><dt>[:lower:]</dt><dd>all lower case letters</dd><dt>[:print:]</dt><dd>all printable characters, including space</dd><dt>[:punct:]</dt><dd>all punctuation characters</dd><dt>[:space:]</dt><dd>all horizontal or vertical whitespace</dd><dt>[:upper:]</dt><dd>all upper case letters</dd><dt>[:xdigit:]</dt><dd>all hexadecimal digits</dd><dt>[=CHAR=]</dt><dd>all characters which are equivalent to CHAR</dd></dl><p>Translation occurs if <strong>-d</strong> is not given and both STRING1 and STRING2 appear. <strong>-t</strong> is only significant when translating. ARRAY2 is extended to length of ARRAY1 by repeating its last character as necessary. Excess characters of ARRAY2 are ignored. Character classes expand in unspecified order; while translating, [:lower:] and [:upper:] may be used in pairs to specify case conversion. Squeezing occurs after translation or deletion.</p><h2 id="bugs" tabindex="-1">BUGS <a class="header-anchor" href="#bugs" aria-label="Permalink to &quot;BUGS&quot;">​</a></h2><p>Full support is available only for safe single-byte locales, in which every possible input byte represents a single character. The C locale is safe in GNU systems, so you can avoid this issue in the shell by running <strong>LC_ALL=C tr</strong> instead of plain <strong>tr</strong>.</p><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Jim Meyering.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p>Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/tr%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/tr\\</a>&gt; <br> or available locally via: info &#39;(coreutils) tr invocation&#39;</p>',20))])}const R=a(l,[["render",c]]);export{f as __pageData,R as default};
